let listingAnnouncements=[],listingExpanded=false,activityRows=[],activityExpanded=false,activityFilter='all';
function renderAnnouncements(){$('#events').innerHTML=(listingExpanded?listingAnnouncements:listingAnnouncements.slice(0,5)).map(x=>`<a class="news-row" href="https://www.asterdex.com/zh-CN/announcement/${encodeURIComponent(x.id)}?category=NEW_LISTING" target="_blank" rel="noopener"><time>${date(x.publishTime)}</time><span>${esc(x.title)}</span><span class="news-arrow">↗</span></a>`).join('')||'<p class="sub">'+t('ann.empty')+'</p>';$('#ann-more').hidden=listingAnnouncements.length<=5;$('#ann-more').textContent=listingExpanded?t('ann.collapse'):t('ann.expand').replace('{n}',listingAnnouncements.length-5)}
$('#ann-more').onclick=()=>{listingExpanded=!listingExpanded;renderAnnouncements()};
function activityKind(x){const t=x.title;return /grid/i.test(t)?'grid':/bStocks|RWA|USD1|dividend/i.test(t)?'rwa':/arena|trad|competition|lucky/i.test(t)?'trade':'other'}
const activityLabels={grid:t('act.grid'),rwa:'RWA / bStocks',trade:t('act.trade'),other:t('act.other')};
function renderActivities(){const a=activityRows.filter(x=>activityFilter==='all'||activityKind(x)===activityFilter);$('#activity-list').innerHTML=(activityExpanded?a:a.slice(0,4)).map(x=>`<a class="activity-card" href="https://www.asterdex.com/zh-CN/announcement/${encodeURIComponent(x.id)}?category=ACTIVITY" target="_blank" rel="noopener"><div class="activity-meta"><span>${activityLabels[activityKind(x)]}</span><time>${t('act.published')}${date(x.publishTime)}</time></div><h3>${esc(x.title)} <span>↗</span></h3>${x.subtitle?`<p>${esc(x.subtitle)}</p>`:''}</a>`).join('')||'<p class="sub">'+t('act.empty')+'</p>';$('#activity-more').hidden=a.length<=4;$('#activity-more').textContent=activityExpanded?t('act.collapse'):t('act.expand').replace('{n}',a.length-4)}
$('#activity-more').onclick=()=>{activityExpanded=!activityExpanded;renderActivities()};$('#activity-tabs').onclick=e=>{const b=e.target.closest('[data-activity]');if(!b)return;activityFilter=b.dataset.activity;activityExpanded=false;document.querySelectorAll('[data-activity]').forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',String(x===b))});renderActivities()};
async function loadActivities(){try{const d=await api('activities');activityRows=d.rows;$('#activity-status').textContent=(d.stale?t('status.cached'):t('status.updated'))+when(d.updatedAt);renderActivities()}catch(e){$('#activity-status').textContent=t('act.unavailable');$('#activity-list').textContent=t('act.loadFail')+e.message}}


const LISTED_SINCE=Date.parse('2026-06-01T00:00:00+08:00'),history=new Map();let querying=false;
const liveMetrics=new Map();let volumeLoading=false,visibleVolume=[];
async function loadVolumeMetrics(){if(volumeLoading||sort!=='volume')return;const queue=visibleVolume.filter(d=>!liveMetrics.has(d.symbol)||Date.now()-liveMetrics.get(d.symbol).fetchedAt>30000);if(!queue.length)return;volumeLoading=true;await Promise.all(Array.from({length:3},async()=>{while(queue.length&&sort==='volume'){const d=queue.shift();try{const k=await api('market-detail?symbol='+encodeURIComponent(d.symbol));liveMetrics.set(d.symbol,{...k,fetchedAt:Date.now()})}catch(e){liveMetrics.set(d.symbol,{openInterest:null,interestError:e.message,fetchedAt:Date.now()})}render()}}));volumeLoading=false}
async function volumeDetail(d){$('#dchain').textContent=t('detail.perp');$('#dgrid').innerHTML=[[t('detail.price'),price(d.price)+' USDT'],[t('detail.chg24'),pct(d.change24)],[t('detail.vol24'),num(d.volume)+' USDT'],[t('detail.oi'),t('common.loading')]].map(v=>`<div><small>${v[0]}</small><b>${esc(v[1])}</b></div>`).join('');$('#detail-note').textContent=t('detail.loading');try{const k=await api('market-detail?symbol='+encodeURIComponent(d.symbol));liveMetrics.set(d.symbol,{...k,fetchedAt:Date.now()});if(!$('#detail').open||$('#dname').textContent!==d.name)return;$('#dgrid').innerHTML=[[t('detail.price'),price(k.price??d.price)+' USDT'],[t('detail.chg24'),pct(k.change24??d.change24)],[t('detail.vol24'),num(k.quoteVolume??d.volume)+' USDT'],[t('detail.oi'),k.openInterest==null?t('common.unavailable'):num(k.openInterest)+' '+d.name]].map(v=>`<div><small>${v[0]}</small><b>${esc(v[1])}</b></div>`).join('');$('#detail-note').textContent=t('detail.rolling')+(k.baseVolume==null?t('common.unavailable'):num(k.baseVolume)+' '+d.name)+t('detail.oiNote')+(k.tickerTime?when(k.tickerTime):t('common.unavailable'))+t('detail.posTime')+(k.interestTime?when(k.interestTime):t('common.unavailable'))+(k.interestError?' · '+k.interestError:'')+(k.tickerError?' · '+k.tickerError:'')+(k.stale?t('status.cachedSuffix'):'');render()}catch(e){if($('#detail').open&&$('#dname').textContent===d.name)$('#detail-note').textContent=t('detail.oiFail')+e.message+t('detail.keepList')}}

let rows=[],sort='date',expanded=false,only=false,saved;try{saved=new Set(JSON.parse(localStorage.getItem('aster-pulse-stars')||'[]'))}catch{saved=new Set()};
const num=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:2}),pct=n=>n!=null&&n!==''&&Number.isFinite(Number(n))?(Number(n)>=0?'+':'')+num(n)+'%':'—',when=t=>new Date(t).toLocaleString(locale(),{timeZone:'Asia/Shanghai',hour12:false}),price=n=>n==null?'—':String(n),date=t=>new Date(t).toLocaleDateString(locale(),{timeZone:'Asia/Shanghai'});
async function api(path){const r=await fetch('/api/'+path);const d=await r.json();if(!r.ok)throw Error(d.error||t('common.reqFail'));return d}
function render(){let a=rows.filter(d=>(sort==='date'||(d.status==='TRADING'&&Number(d.volume)>=100000))&&(sort!=='peak'||(d.onboard>=LISTED_SINCE&&Number.isFinite(d.peak)))&&d.name.toLowerCase().includes($('#search').value.toLowerCase())&&(!only||saved.has(d.name)));a.sort((a,b)=>sort==='date'?b.onboard-a.onboard:sort==='volume'?Number(b.volume)-Number(a.volume):sort==='now'?Number(b.change24)-Number(a.change24):(b.peak??-Infinity)-(a.peak??-Infinity));$('#gainhead').textContent=sort==='volume'?t('table.chg'):sort==='peak'?t('table.topGain'):t('table.chg24');$('#volumehead').textContent=sort==='volume'?t('table.oi'):t('table.volume');$('#drawhead').textContent=sort==='volume'?t('table.volUsdt'):t('table.fromPeak');$('#market-table').classList.toggle('volume-mode',sort==='volume');const eligible=rows.filter(d=>d.status==='TRADING'&&Number(d.volume)>=100000&&d.onboard>=LISTED_SINCE);const done=eligible.filter(d=>Number.isFinite(d.peak)).length;$('#market-note').textContent=sort==='date'?t('markets.noteDate'):t('markets.noteFilter')+(sort==='volume'?t('markets.noteVolume'):'')+(sort==='peak'?t('markets.peakNote').replace('{done}',done).replace('{total}',eligible.length).replace('{rest}',querying?t('markets.peakLoading'):t('markets.peakIncomplete')):t('markets.noteChg'));visibleVolume=sort==='volume'?(expanded?a:a.slice(0,10)):[];const toggle=$('#market-toggle');toggle.hidden=a.length<=10;toggle.textContent=expanded?t('markets.collapse'):t('markets.expand').replace('{n}',a.length-10);toggle.setAttribute('aria-expanded',String(expanded));$('#rows').innerHTML=(expanded?a:a.slice(0,10)).map(d=>`<tr data-name="${esc(d.symbol)}" tabindex="0" role="button" aria-label="${t('markets.viewDetail').replace('{name}',esc(d.name))}"><td><div class="coin"><button class="star ${saved.has(d.name)?'saved':''}" data-star="${esc(d.name)}" aria-label="${t('markets.watchCoin').replace('{name}',esc(d.name))}">${saved.has(d.name)?'★':'☆'}</button><div><b>${esc(d.name)}</b><div class="chain">${date(d.onboard)} · ${d.status==='TRADING'?t('markets.trading'):t('markets.settling')}${d.discovered?t('markets.new'):''}</div></div></div></td><td>${esc(price(d.price))}</td><td class="${sort==='volume'?'':'green'}">${sort==='volume'?pct(d.change24):sort==='peak'?(d.peak==null?t('markets.viewDetailLink'):pct(d.peak)):pct(d.change24)}</td><td>${sort==='volume'?num(d.volume):d.drawdown==null?'—':pct(d.drawdown)}</td><td class="sparkcol">${sort==='volume'?(liveMetrics.get(d.symbol)?.openInterest!=null?num(liveMetrics.get(d.symbol).openInterest)+' '+esc(d.name):liveMetrics.has(d.symbol)?t('common.unavailable'):t('common.loading')):num(d.volume/1000)+'K'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">'+t('markets.empty')+'</td></tr>';if(sort==='volume')queueMicrotask(loadVolumeMetrics)}
async function loadMarkets(){try{let d=await api('markets');rows=d.rows.map(x=>{const k=history.get(x.symbol);return k?{...x,peak:(Math.max(k.high,Number(x.price))/k.open-1)*100,drawdown:(Number(x.price)/Math.max(k.high,Number(x.price))-1)*100}:x});$('#market-status').textContent=(d.stale?t('status.cachedFull'):t('status.official'))+' · '+when(d.updatedAt);render();if(sort==='peak')loadPeaks()}catch(e){$('#market-status').textContent=t('markets.unavailable');$('#market-note').textContent=e.message}}
$('#market-toggle').onclick=()=>{expanded=!expanded;render();if(!expanded)$('#tabs').scrollIntoView({block:'start',behavior:'smooth'})};
$('#search').addEventListener('input',()=>{expanded=false;render()});$('#watch').onclick=()=>{expanded=false;only=!only;$('#watch').classList.toggle('on',only);render()};$('#tabs').onclick=e=>{if(!e.target.dataset.sort)return;expanded=false;sort=e.target.dataset.sort;document.querySelectorAll('#tabs button').forEach(b=>b.classList.toggle('on',b===e.target));render();if(sort==='peak')loadPeaks()};
async function loadPeaks(){if(querying)return;querying=true;render();const queue=rows.filter(d=>d.status==='TRADING'&&Number(d.volume)>=100000&&d.onboard>=LISTED_SINCE&&(!history.has(d.symbol)||Date.now()-history.get(d.symbol).updatedAt>300000));await Promise.all(Array.from({length:3},async()=>{while(queue.length){const d=queue.shift();try{const k=await api('detail?symbol='+encodeURIComponent(d.symbol));if(k.stale)throw Error(t('markets.historyStale'));history.set(d.symbol,k);const current=rows.find(x=>x.symbol===d.symbol);if(current)Object.assign(current,{peak:(Math.max(k.high,Number(current.price))/k.open-1)*100,drawdown:(Number(current.price)/Math.max(k.high,Number(current.price))-1)*100})}catch{history.delete(d.symbol);const current=rows.find(x=>x.symbol===d.symbol);if(current){delete current.peak;delete current.drawdown}}render()}}));querying=false;render()}
async function detail(symbol){let d=rows.find(x=>x.symbol===symbol);$('#dname').textContent=d.name;$('#dchain').textContent=t('detail.listedAt')+when(d.onboard);$('#dgrid').innerHTML='<p>'+t('detail.loadingHistory')+'</p>';$('#detail').showModal();$('#dtrade').href='https://www.asterdex.com/zh-CN/trade/pro/futures/'+encodeURIComponent(symbol);$('#dx').href='https://x.com/search?q='+encodeURIComponent('$'+d.name+' Aster')+'&f=live';if(sort==='volume'){await volumeDetail(d);return}try{let k=await api('detail?symbol='+encodeURIComponent(symbol));if(!k.stale){history.set(symbol,k);Object.assign(d,{peak:k.peak,drawdown:k.drawdown})}if(!$('#detail').open||$('#dname').textContent!==d.name)return;$('#dgrid').innerHTML=[[t('detail.open'),price(k.open)],[t('detail.latest'),price(k.price)],[t('detail.high'),price(k.high)],[t('detail.topGain'),pct(k.peak)],[t('detail.gain'),pct(k.now)],[t('detail.drawdown'),pct(k.drawdown)]].map(v=>`<div><small>${v[0]}</small><b>${esc(v[1])}</b></div>`).join('');$('#detail-note').textContent=t('detail.note')+when(k.updatedAt)+(k.stale?t('status.cachedSuffix'):'');render()}catch(e){$('#dgrid').textContent=t('detail.loadFail')+e.message}}
$('#rows').onclick=e=>{let b=e.target.closest('[data-star]');if(b){let n=b.dataset.star;saved.has(n)?saved.delete(n):saved.add(n);try{localStorage.setItem('aster-pulse-stars',JSON.stringify([...saved]))}catch{}render();return}let r=e.target.closest('[data-name]');if(r)detail(r.dataset.name)};$('#rows').onkeydown=e=>{if(e.target.matches('tr')&&e.key==='Enter')detail(e.target.dataset.name)};$('.close').onclick=()=>$('#detail').close();
let tokenStatsCache=null;function renderTokenStats(d){const up=d.change24!=null&&Number(d.change24)>=0;$('#token-stats').innerHTML=`<div class="metric"><div class="title">${t('token.price')}</div><div class="number">${d.price==null?'—':price(d.price)}<span class="unit">USDT</span></div><div class="minor">${d.change24==null?t('token.chgUnavailable'):(up?'+':'')+Number(d.change24).toFixed(2)+'% · 24h'}${d.priceStale?t('status.cachedShort'):''}</div></div><div class="metric"><div class="title">${t('token.staked')}</div><div class="number">${d.staked==null?'—':(d.staked/1000000).toFixed(1)}<span class="unit">${d.staked==null?'ASTER':t('token.million')}</span></div><div class="minor">${d.staked==null?(d.stakedError||t('token.stakedUnavailable')):t('token.stakedNote').replace('${usd}',Math.round(d.stakedUsd/1000000)).replace('${at}',date(d.stakedAt))+(d.stakedStale?t('status.cachedShort'):'')}</div></div><div class="metric"><div class="title">${t('token.burned')}</div><div class="number">${d.burned==null?'—':(d.burned/100000000).toFixed(2)}<span class="unit">${d.burned==null?'ASTER':t('token.yi')}</span></div><div class="minor">${d.burned==null?(d.burnedError||t('token.burnedUnavailable')):t('token.burnedNote')+(d.burnedStale?t('status.cachedShort'):'')}</div></div>`;$('#token-status').textContent=(d.stale?t('status.cachedFull'):t('token.statusOk'))+' · '+when(d.updatedAt);if(buybackSnapshot){$('#buy-note').textContent=scopeText(buybackSnapshot.scope)+t('buy.chunked')+(d.burned!=null?t('token.burnedLine').replace('{n}',num(d.burned)):t('token.burnedLineUnavailable'))}}
