// ===== BEGIN SHARE CUSTOM =====
// 分享图自定义：模板（浅色/深色/品牌金）× 回购数据开关。
// 尺寸写死默认 4:5（1080×1350）；社区热度、一句话结论、来源水印三个开关已
// 删，图里也不再画社区热度、结论、水印与“独立社区观察站 · x.com/zsf11221”。
// 默认选项（浅色 + 只开回购数据）复现旧图：此时走
// drawShareClassic()，绘制代码与改动前逐行一致，默认图行为不变。
// 选项存在 localStorage（aster-pulse-share-opts）。
// 删除：本段 + HTML 里的 SHARE CUSTOM 段 + <style> 里的 SHARE CUSTOM 段
// 即恢复只有默认图；其它功能不受影响。
const SHARE_OPTS_KEY='aster-pulse-share-opts';
const SHARE_DEFAULTS={template:'light',showBuyback:true};
let shareOpts={...SHARE_DEFAULTS};
try{const saved=JSON.parse(localStorage.getItem(SHARE_OPTS_KEY)||'null');if(saved&&typeof saved==='object')shareOpts={template:['light','dark','gold'].includes(saved.template)?saved.template:'light',showBuyback:saved.showBuyback!==false}}catch{}
function saveShareOpts(){try{localStorage.setItem(SHARE_OPTS_KEY,JSON.stringify(shareOpts))}catch{}}
const SHARE_PALETTES={
light:{bg:'#F7F4EB',ink:'#172B59',accent:'#193A86',muted:'#657087',line:'#CED4DF',warn:'#9A5928'},
dark:{bg:'#101213',ink:'#eeeae5',accent:'#e8ba95',muted:'#92979a',line:'#2d3032',warn:'#e8ba95'},
gold:{bg:'#171310',ink:'#f5ead6',accent:'#e8ba95',muted:'#b7a98f',line:'#3c342d',warn:'#e8ba95'},
};
const SHARE_SIZE=[1080,1350]; // 尺寸写死默认 4:5，不再提供其它尺寸。
// 经典绘制：改动前的默认图（浅色 1080×1350），代码逐行原样搬入函数，
// 坐标、颜色、文案全部不变；只有默认选项组合才走这里。
function drawShareClassic(x,d){
x.fillStyle='#F7F4EB';x.fillRect(0,0,1080,1350);const text=(v,left,top,size=28,color='#172B59',weight=400)=>{x.fillStyle=color;x.font=weight+' '+size+'px Arial,"Microsoft Yahei",sans-serif';x.fillText(v,left,top)};x.fillStyle='#193A86';x.fillRect(0,0,1080,18);text('ASTER / PULSE',72,105,28,'#193A86',700);text(t('share.canvasTitle'),72,195,64,'#172B59',700);text(t('share.bjPrefix')+d.days.at(-1).day,76,252,27,'#657087');text(d.stale?t('share.cachedSnap'):t('share.officialSnap'),76,300,25,d.stale?'#9A5928':'#657087');const totals=d.days.reduce((s,v)=>({qty:s.qty+Number(v.qty),spent:s.spent+Number(v.spent)}),{qty:0,spent:0});const cards=[[t('buy.today'),d.days.at(-1)],[t('buy.yesterday'),d.days.at(-2)],[t('buy.weekTotal'),totals]];cards.forEach(([title,v],i)=>{const y=355+i*208;x.strokeStyle='#CED4DF';x.beginPath();x.moveTo(72,y);x.lineTo(1008,y);x.stroke();text(title,76,y+43,28,'#657087');text(num(v.qty)+' ASTER',76,y+111,52,'#172B59',700);text(t('buy.volume')+num(v.spent)+' USDT',76,y+159,28,'#657087')});text(tokenStatsCache&&tokenStatsCache.burned!=null?t('share.burnedLine').replace('{n}',num(tokenStatsCache.burned)):t('share.burnedLineNA'),76,1036,28,'#657087');text(t('share.dataTime')+when(d.updatedAt),76,1091,24,'#657087');text(t('share.source'),76,1134,24,'#657087');text(t('share.wallet'),76,1177,24,'#657087');text(t('share.note'),76,1220,24,'#657087');
}
// 单行截断：超宽时末尾加 …
function shareFitOneLine(x,fontStr,v,maxW){
x.font=fontStr;
if(x.measureText(v).width<=maxW)return String(v);
let s=String(v);
while(s.length>1&&x.measureText(s+'…').width>maxW)s=s.slice(0,-1);
return s+'…';
}
// 自适应绘制：非默认选项组合走这里。流式布局（标题→回购→底部信息），底部信息锚定在画布底部。
function drawShareAdaptive(x,opts){
const P=SHARE_PALETTES[opts.template]||SHARE_PALETTES.light;
const d=buybackSnapshot;
const [W,H]=SHARE_SIZE;
const s=W/1080,m=72*s,maxW=W-2*m;
const font=(size,weight=400)=>weight+' '+Math.round(size*s)+'px Arial,"Microsoft Yahei",sans-serif';
const text=(v,left,top,size=28,color=P.ink,weight=400)=>{x.fillStyle=color;x.font=font(size,weight);x.fillText(v,left,top)};
x.fillStyle=P.bg;x.fillRect(0,0,W,H);
x.fillStyle=P.accent;x.fillRect(0,0,W,Math.round(18*s));
let y=105*s;
text('ASTER / PULSE',m,y,28,P.accent,700);y+=90*s;
text(t('share.canvasTitle'),m,y,64,P.ink,700);y+=57*s;
const dayStr=d?d.days.at(-1).day:'';
text(t('share.bjPrefix')+dayStr,m+4*s,y,27,P.muted);y+=48*s;
text(d?(d.stale?t('share.cachedSnap'):t('share.officialSnap')):'',m+4*s,y,25,d&&d.stale?P.warn:P.muted);y+=55*s;
if(opts.showBuyback&&d){
const totals=d.days.reduce((sv,v)=>({qty:sv.qty+Number(v.qty),spent:sv.spent+Number(v.spent)}),{qty:0,spent:0});
const cards=[[t('buy.today'),d.days.at(-1)],[t('buy.yesterday'),d.days.at(-2)],[t('buy.weekTotal'),totals]];
cards.forEach(([title,v],i)=>{x.strokeStyle=P.line;x.beginPath();x.moveTo(m,y);x.lineTo(W-m,y);x.stroke();text(title,m+4*s,y+43*s,28,P.muted);text(num(v.qty)+' ASTER',m+4*s,y+111*s,52,P.ink,700);text(t('buy.volume')+num(v.spent)+' USDT',m+4*s,y+159*s,28,P.muted);y+=208*s});
}
const burnedY=H-314*s;
const footY=H-67*s,noteY=footY-63*s,walletY=noteY-43*s,sourceY=walletY-43*s,dataY=sourceY-43*s;
text(tokenStatsCache&&tokenStatsCache.burned!=null?t('share.burnedLine').replace('{n}',num(tokenStatsCache.burned)):t('share.burnedLineNA'),m+4*s,burnedY,28,P.muted);
if(d)text(t('share.dataTime')+when(d.updatedAt),m+4*s,dataY,24,P.muted);
text(t('share.source'),m+4*s,sourceY,24,P.muted);
text(t('share.wallet'),m+4*s,walletY,24,P.muted);
text(t('share.note'),m+4*s,noteY,24,P.muted);
}
function syncShareSettingsUI(){
document.querySelectorAll('#share-settings [data-share-opt]').forEach(b=>{
const k=b.dataset.shareOpt;
const on=(k==='template'||k==='size')?shareOpts[k]===b.dataset.value:!!shareOpts[k];
b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on));
});
}
let shareGenRunning=false,shareGenDirty=false;
async function generateShareImage(triggerBtn){
if(!buybackSnapshot)return;
// 串行化：快速连点选项时，后一次调用只标记 dirty 就返回，当前这次画完
// 后立刻用最新选项重画一遍。避免两个并发绘制互相覆盖，预览停留在旧选项。
if(shareGenRunning){shareGenDirty=true;return}
shareGenRunning=true;
if(triggerBtn){triggerBtn.disabled=true;triggerBtn.textContent=t('share.generating')}
try{
do{
shareGenDirty=false;
const c=document.createElement('canvas');
const [W,H]=SHARE_SIZE;
c.width=W;c.height=H;
const x=c.getContext('2d');
const isDefault=shareOpts.template==='light'&&shareOpts.showBuyback;
if(isDefault)drawShareClassic(x,buybackSnapshot);else drawShareAdaptive(x,shareOpts);
const blob=await new Promise((resolve,reject)=>c.toBlob(v=>v?resolve(v):reject(Error(t('share.imgFail'))),'image/png'));
if(shareUrl)URL.revokeObjectURL(shareUrl);
const dayStr=buybackSnapshot?buybackSnapshot.days.at(-1).day:'';
shareFile=new File([blob],'Aster-Pulse-'+dayStr+'.png',{type:'image/png'});
shareUrl=URL.createObjectURL(blob);
$('#share-preview').src=shareUrl;
$('#share-download').href=shareUrl;$('#share-download').download=shareFile.name;
$('#share-native').hidden=!(navigator.canShare&&navigator.canShare({files:[shareFile]}));
$('#share-message').textContent=t('share.saved');
}while(shareGenDirty);
}catch(e){
$('#share-message').textContent=t('share.genFail')+e.message;
$('#buy-note').textContent=t('share.genFail')+e.message;
}finally{
shareGenRunning=false;
if(triggerBtn){triggerBtn.disabled=!buybackSnapshot;triggerBtn.textContent=t('share.btn')}
}
}
function openShare(triggerBtn){
$('#share-title').textContent=t('share.dialogTitle');
syncShareSettingsUI();
$('#share-dialog').showModal();
generateShareImage(triggerBtn);
}
$('#share-buyback').onclick=e=>{if(!buybackSnapshot)return;openShare(e.currentTarget)};
$('#share-settings').addEventListener('click',e=>{
const b=e.target.closest('[data-share-opt]');if(!b||b.disabled)return;
const k=b.dataset.shareOpt;
if(k==='template')shareOpts[k]=b.dataset.value;else shareOpts[k]=!shareOpts[k];
saveShareOpts();syncShareSettingsUI();generateShareImage();
});
// ===== END SHARE CUSTOM =====



