let communityCache=null;let communityExpanded=false;
function renderCommunity(d){const n=$('#community-notice');if(!d.available){$('#community-status').textContent=t('community.notConnected');$('#community-list').innerHTML='<p class="sub">'+t('community.notConnectedNote')+'</p>';if(n)n.textContent=t('community.noticeOff');return}if(n)n.textContent=t('community.noticeOn');$('#community-status').textContent=(d.stale?t('status.cachedFull'):t('community.searchLabel'))+' · '+when(d.updatedAt);const shown=communityExpanded?d.tweets:d.tweets.slice(0,5);$('#community-list').innerHTML=d.tweets.length?shown.map(tw=>`<a class="tweet-item" href="${esc(tw.url)}" target="_blank" rel="noopener"><div class="tweet-meta"><b>${esc(tw.author.name||tw.author.username||t('community.xUser'))}</b>${tw.official?' <span class="official-badge">'+t('community.official')+'</span>':''}<span>@${esc(tw.author.username||'')}</span><time>${tw.createdAt?when(tw.createdAt):''}</time></div><p>${esc(tw.text)}</p><div class="tweet-metrics">${tw.likes==null?'':'♥ '+num(tw.likes)+' · '}${tw.retweets==null?'':'↻ '+num(tw.retweets)+' · '}${t('community.viewOnX')}</div></a>`).join(''):'<p class="sub">'+t('community.empty')+'</p>';const tg=$('#community-toggle');if(tg){if(d.tweets.length>5){tg.style.display='';tg.textContent=communityExpanded?t('community.showLess'):t('community.showMore').replace('{n}',String(d.tweets.length-5));tg.onclick=()=>{communityExpanded=!communityExpanded;if(communityCache)renderCommunity(communityCache)}}else{tg.style.display='none'}}}
async function loadCommunity(){try{const d=await api('community');communityCache=d;renderCommunity(d)}catch(e){if(communityCache){renderCommunity({...communityCache,stale:true})}else{$('#community-status').textContent=t('community.notConnected');$('#community-list').innerHTML='<p class="sub">'+t('community.notConnectedNote')+'</p>'}}}
loadCommunity();setInterval(loadCommunity,1800000);

// ===== BEGIN DAILY BRIEF =====
// 每日异动：前端渲染（GET /api/daily-brief）。区块默认 hidden，
// 取到数据才显示；接口 404（DAILY_BRIEF_ENABLED=false）或失败时保持隐藏，
// 其它功能不受影响。删除：本段 + HTML 里的 DAILY BRIEF 段 +
// <style> 里的 DAILY BRIEF 段 + 后端 dailyBrief() + README 对应小节。
let dailyBriefCache=null,dinoFilter='all';
function briefVerdictText(d){return t('brief.verdict'+({overheated:'Overheated',strong:'Strong',watch:'Watch',quiet:'Quiet'}[d.verdict]||'Quiet'))}
// 点位显示：服务端已按 4 位有效数字取整，这里只保留小数位（不四舍五入到 2 位，
// 否则 0.009449 这类小价会变成 0.01）。
const fmtPx=v=>v==null?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:8});
function renderDailyBrief(d){
const sec=$('#daily-brief');if(!sec)return;
sec.hidden=false;
$('#brief-date').textContent=d.date?date(Date.parse(d.date+'T00:00:00+08:00')):'';
$('#brief-status').textContent=(d.stale?t('status.cached'):t('status.updated'))+when(d.updatedAt);
const joiner=lang==='en'?'. ':'；',ender=lang==='en'?'.':'。';
const s=[];
if(d.top)s.push(t('brief.summaryTop').replace('{name}',d.top.name).replace('{chg}',pct(d.top.change24)));
if(d.events&&d.events.length)s.push(t('brief.summaryEvent').replace('{event}',lang==='en'?d.events[0].en.title:d.events[0].zh.title));
else if(d.newest)s.push(t('brief.summaryNew').replace('{name}',d.newest.name).replace('{date}',date(d.newest.onboard)));
$('#brief-summary').textContent=s.length?s.join(joiner)+ender:'';
const top=d.top;
$('#brief-top').innerHTML=top?`<div class="brief-topcard"><div class="brief-tophead"><span class="eyebrow">${t('brief.topLabel')}</span><span class="brief-score">${t('brief.score').replace('{n}',d.score)}</span></div><div class="brief-coin"><b>${esc(top.name)}</b><span class="brief-price">${esc(price(top.price))} USDT</span><span class="brief-chg green">${pct(top.change24)}</span></div><p class="brief-verdict">${esc(briefVerdictText(d))}</p><div class="brief-signals"><div class="brief-signal"><small>${t('brief.signalChange')}</small><b>${pct(top.change24)}</b><span>+${d.scoreParts.change} ${t('brief.scorePoint')}</span></div><div class="brief-signal"><small>${t('brief.signalVolume')}</small><b>${top.volume==null?'—':num(top.volume)+' USDT'}</b><span>+${d.scoreParts.volume} ${t('brief.scorePoint')}</span></div><div class="brief-signal"><small>${t('brief.signalFunding')}</small><b>${top.fundingRate==null?t('brief.fundingNA'):(top.fundingRate*100).toFixed(2)+'%'}</b><span>${top.openInterest==null?'':t('brief.oiLine').replace('{n}',num(top.openInterest)+' '+esc(top.name))+' · '}+${d.scoreParts.funding} ${t('brief.scorePoint')}</span></div><div class="brief-signal"><small>${t('brief.signalGap')}</small><b>${d.secondGap==null?'—':pct(d.secondGap)}</b><span>+${d.scoreParts.gap} ${t('brief.scorePoint')}</span></div></div></div>`:'<p class="sub">'+t('brief.unavailable')+'</p>';
const ideas=d.ideas||[];
$('#brief-ideas').innerHTML=ideas.length?ideas.map(it=>{
const idea=it.idea||{};
const dir=idea.direction||'none';
const dirLabel=t('brief.idea'+({noChase:'NoChase',tryLong:'TryLong',watch:'Watch',none:'None'}[dir]||'None'));
const entryLabel=dir==='watch'?t('brief.ideaBreakout'):t('brief.ideaEntry');
const levels=[];
if(idea.entry!=null)levels.push(entryLabel+' <b>'+fmtPx(idea.entry)+'</b>');
if(idea.stop!=null)levels.push(t('brief.ideaStop')+' <b>'+fmtPx(idea.stop)+'</b>');
if(idea.target!=null)levels.push(t('brief.ideaTarget')+' <b>'+fmtPx(idea.target)+'</b>');
const reason=idea.reason?(lang==='en'?idea.reason.en:idea.reason.zh):'';
return `<div class="brief-idea"><div class="brief-idea-head"><span><b>${esc(it.name)}</b><span class="minor"> ${esc(price(it.price))} USDT</span></span><span><span class="tag">${dirLabel}</span> <span class="green">${pct(it.change24)}</span></span></div>${levels.length?`<div class="brief-idea-levels">${levels.map(l=>`<span>${l}</span>`).join('')}</div>`:''}${reason?`<p>${esc(reason)}</p>`:''}</div>`;
}).join(''):'<p class="sub">'+t('brief.ideaNone')+'</p>';
const list=(d.dino||[]).filter(x=>dinoFilter==='all'||Number(x.change24)>=20);
$('#brief-dino').innerHTML=list.length?list.map(x=>{const c=Number(x.change24);const tag=c>=50?t('brief.dinoStrong'):c>=20?t('brief.dinoWatchTag'):t('brief.dinoFlat');return `<div class="brief-dino-row"><span><b>${esc(x.name)}</b><span class="minor">${esc(price(x.price))} USDT</span></span><span><span class="tag">${tag}</span> <span class="green">${pct(x.change24)}</span></span></div>`}).join(''):'<p class="sub">'+t('brief.dinoEmpty')+'</p>';
$('#brief-events').innerHTML=(d.events||[]).length?(d.events||[]).map(ev=>{const v=lang==='en'?ev.en:ev.zh;return `<div class="brief-event"><time>${ev.date.slice(5).replace('-','/')}</time><div><b>${esc(v.title)}</b><p>${esc(v.note)}</p></div></div>`}).join(''):'<p class="sub">'+t('brief.eventsEmpty')+'</p>';
}
async function loadDailyBrief(){try{const d=await api('daily-brief');dailyBriefCache=d;renderDailyBrief(d)}catch(e){const sec=$('#daily-brief');if(sec)sec.hidden=true}}
$('#brief-dino-filter').onclick=e=>{const b=e.target.closest('[data-dino]');if(!b)return;dinoFilter=b.dataset.dino;document.querySelectorAll('#brief-dino-filter [data-dino]').forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',String(x===b))});if(dailyBriefCache)renderDailyBrief(dailyBriefCache)};
loadDailyBrief();setInterval(loadDailyBrief,300000);
// ===== END DAILY BRIEF =====
